module mux4to1 (in0, in1, in2, in3, sel, out);
input [3:0] in0, in1, in2, in3;
input [1:0] sel;
output out;

reg out;

always @ (sel, in0, in1, in2, in3)
begin
    case (sel)
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = in3;
        default: out = 1'b0;
    endcase
end

endmodule

