module POR (
  input power,
  input clk,
  output reset
);

parameter rst_time = 10; // length of time the reset signal should be asserted

reg [31:0] rst_counter;
reg reset_reg;

always @(posedge clk) begin
  if (power) begin
    rst_counter <= rst_counter + 1;
    if (rst_counter >= rst_time) begin
      reset_reg <= 1'b1;
      rst_counter <= 0;
    end
  end else begin
    reset_reg <= 1'b0;
    rst_counter <= 0;
  end
end

assign reset = reset_reg;

endmodule

