module binary_counter(
  input clk,
  input rst,
  output reg [3:0] count
);

  always @(posedge clk, negedge rst) begin
    if (rst == 0) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

